#pragma once
#include <stdint.h>

// Small anti-aliased proportional UI fonts generated by tools/gen_uifont.py (ASCII 32..126).
// Pixel byte: high nibble = coverage, low nibble = outline coverage.
typedef struct {
    uint8_t h, pad;
    uint8_t adv[95];
    uint8_t w[95];
    uint32_t off[95];
    const uint8_t *px;
} uifont_t;

extern const uifont_t ui_s, ui_m;
